{% if found_project_name %}
{% set project_display = found_project_id ~ " (" ~ found_project_name ~ ")" %}
{% else %}
{% set project_display = found_project_id %}
{% endif %}
{% endif %}

{% for page in layout %}
<div class="page-break print-format-wrapper order-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>
	{%- if doc.meta.is_submittable and doc.docstatus==2-%}
		<div class="text-center" document-status="cancelled">
			<h4 style="margin-top: 20px;">{{ _("CANCELLED") }}</h4>
		</div>
	{%- endif -%}
	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}
		<div class="text-center" document-status="draft">
			<h4 style="margin-top: 20px !important;">{{ _("DRAFT") }}</h4>
		</div>
	{%- endif -%}

	<div class="print-format-body">
        <!-- 基本信息表格 -->
        <table class="table table-bordered info-table mb-3">
            <tbody>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">单号:</span>
                        <span class="info-value text-bold">{{ doc.name }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">日期:</span>
                        <span class="info-value">{{ frappe.utils.format_date(doc.creation) }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">用途:</span>
                        <span class="info-value">{{ _(doc.purpose) or "&nbsp;" }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">项目:</span>
                        <span class="info-value text-bold">{{ project_display or "&nbsp;" }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" colspan="2">
                        <span class="info-label font-weight-bold">关联 ({{ source_label }}):</span>
                        <span class="info-value">{{ source_name or "&nbsp;" }}</span>
                    </td>
                </tr>
            </tbody>
        </table>

        <!-- 物料明细表格 -->
        <table class="table table-bordered items-table mb-3">
            <thead class="table-header">
                <tr>
                    <th class="text-center" style="width: 6%;">序号</th>
                    <th class="text-left" style="width: 36%;">物料信息</th>
                    <th class="text-left" style="width: 15%;">源仓库</th>
                    <th class="text-left" style="width: 20%;">批次/序列号</th>
                    <th class="text-right" style="width: 15%;">数量</th>
                    <th class="text-center" style="width: 8%;">✔</th>
                </tr>
            </thead>
            <tbody>
                {%- for item in doc.locations -%}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td class="item-info-cell">
                        <div class="item-code text-bold">{{ item.item_code }}</div>
                        <div class="item-name">{{ item.item_name }}</div>
                    </td>
                    <td class="warehouse-cell">{{ item.warehouse or "--" }}</td>
                    <td class="batch-serial-cell">
                        {%- if item.batch_no -%}
                        <div class="secondary-text">[批] {{ item.batch_no }}</div>
                        {% endif %}
                        {%- if item.serial_no -%}
                        <div class="secondary-text">[序] {{ item.serial_no }}</div>
                        {% endif %}
                        {%- if not item.batch_no and not item.serial_no -%}
                        &nbsp;
                        {% endif %}
                    </td>
                    <td class="text-right quantity-cell">
                        <span class="quantity-value text-bold">{{ item.picked_qty }}</span>
                        <span class="quantity-uom">{{ item.uom }}</span>
                    </td>
                    <td class="text-center check-cell">
                        <div class="check-box-outline"></div>
                    </td>
                </tr>
                {%- endfor -%}
            </tbody>
        </table>

        <!-- 备注区域 -->
        <div class="remarks-box mb-3">
            <div class="remarks-label font-weight-bold mb-2">备注:</div>
            <div class="remarks-content">{{ doc.remarks or "&nbsp;" }}</div>
        </div>

        <!-- 签名区域 -->
        <table class="table table-borderless signature-table">
            <tbody>
                <tr>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">制单人:</div>
                        {%- if doc.owner -%}
                        <div class="signature-name text-bold mt-2">{{ doc.owner }}</div>
                        {%- else -%}
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        {% endif %}
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">拣货人:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">复核人:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">接收人:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                </tr>
            </tbody>
        </table>
	</div>
</div>
{% endfor %}

