html:
{%- macro add_header(doc, letter_head, no_letterhead) -%}
{% if letter_head and not no_letterhead %}
<div class="letter-head">{{ letter_head }}</div>
{% endif %}
{%- endmacro -%}

{% set source_label = "无" %}
{% set source_name = "" %}
{% set project_display = "" %}
{% set req_type_map = {
    "Purchase": "采购",
    "Material Transfer": "材料转移/调拨",
    "Material Issue": "领料/出库",
    "Manufacture": "生产制造",
    "Customer Provided": "客户提供"
} %}

{# --- 1. 尝试从子表第一行获取关联来源与项目 --- #}
{% set found_project_id = "" %}
{% if doc.items and doc.items|length > 0 %}
{% set first_line = doc.items[0] %}

{# 获取项目ID #}
{% if first_line.project %}
{% set found_project_id = first_line.project %}
{% endif %}

{# 获取来源单据 #}
{% if first_line.work_order %}
{% set source_label = "生产工单" %}
{% set source_name = first_line.work_order %}
{% elif first_line.sales_order %}
{% set source_label = "销售订单" %}
{% set source_name = first_line.sales_order %}
{% elif first_line.job_card %}
{% set source_label = "作业卡" %}
{% set source_name = first_line.job_card %}
{% endif %}
{% endif %}

{# --- 2. 拼接项目名称: ID (名称) --- #}
{% if found_project_id %}
{% set found_project_name = frappe.db.get_value("Project", found_project_id, "project_name") %}
{% if found_project_name %}
{% set project_display = found_project_id ~ " (" ~ found_project_name ~ ")" %}
{% else %}
{% set project_display = found_project_id %}
{% endif %}
{% endif %}

<div class="page-break print-format-wrapper">
    <div id="header-html" class="hidden-pdf">
        {{ add_header(doc, letter_head, no_letterhead) }}
    </div>

    <div class="print-format-body">
        {% if doc.title %}
        <div class="text-center mb-3 mt-3">
            <div style="font-size: 16px; font-weight: bold;">{{ doc.title }}</div>
        </div>
        {% endif %}

        <!-- 基本信息表格 -->
        <table class="table table-bordered info-table mb-3">
            <tbody>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">单号:</span>
                        <span class="info-value text-bold">{{ doc.name }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">日期:</span>
                        <span class="info-value">{{ frappe.utils.format_date(doc.transaction_date) }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">类型:</span>
                        <span class="info-value">{{ req_type_map.get(doc.material_request_type, doc.material_request_type) }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">项目:</span>
                        <span class="info-value text-bold">{{ project_display or "&nbsp;" }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" colspan="2">
                        <span class="info-label font-weight-bold">关联 ({{ source_label }}):</span>
                        <span class="info-value">{{ source_name or "&nbsp;" }}</span>
                    </td>
                </tr>
            </tbody>
        </table>

        <!-- 物料明细表格 -->
        <table class="table table-bordered items-table mb-3">
            <thead class="table-header">
                <tr>
                    <th class="text-center" style="width: 6%;">序号</th>
                    <th class="text-left" style="width: 36%;">物料信息</th>
                    <th class="text-left" style="width: 20%;">目标仓库</th>
                    <th class="text-left" style="width: 15%;">需求日期</th>
                    <th class="text-right" style="width: 15%;">数量</th>
                    <th class="text-center" style="width: 8%;">✔</th>
                </tr>
            </thead>
            <tbody>
                {% for item in doc.items %}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td class="item-info-cell">
                        <div class="item-code text-bold">{{ item.item_code }}</div>
                        <div class="item-name">{{ item.item_name }}</div>
                        {% if item.description and item.description != item.item_name %}
                        <div class="item-description secondary-text">{{ item.description | striptags }}</div>
                        {% endif %}
                    </td>
                    <td class="warehouse-cell">{{ item.warehouse or "--" }}</td>
                    <td>{{ frappe.utils.format_date(item.schedule_date) }}</td>
                    <td class="text-right quantity-cell">
                        <span class="quantity-value text-bold">{{ item.qty }}</span>
                        <span class="quantity-uom">{{ item.uom }}</span>
                    </td>
                    <td class="text-center check-cell">
                        <div class="check-box-outline"></div>
                    </td>
                </tr>
                {% endfor %}
            </tbody>
        </table>

        <!-- 备注区域 -->
        <div class="remarks-box mb-3">
            <div class="remarks-label font-weight-bold mb-2">备注:</div>
            <div class="remarks-content">{{ doc.remarks or "&nbsp;" }}</div>
        </div>

        <!-- 签名区域 -->
        <table class="table table-borderless signature-table">
            <tbody>
                <tr>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">申请人 (制单):</div>
                        {% if doc.owner %}
                        <div class="signature-name text-bold mt-2">{{ doc.owner }}</div>
                        {% else %}
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        {% endif %}
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">部门主管:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">计划/采购:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">批准:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                </tr>
            </tbody>
        </table>
    </div>
</div>

