.contract-header {
    text-align: center;
    margin-bottom: 20px;
}

.contract-number {
    text-align: right;
    font-size: 12px;
    margin-bottom: 10px;
}

.header-title {
    text-align: center;
    font-size: 24px;
    font-weight: bold;
    margin: 15px 0;
    letter-spacing: 3px;
}

.contract-parties {
    margin-bottom: 15px;
    font-size: 13px;
}

.party-line {
    margin-bottom: 8px;
    display: flex;
    align-items: baseline;
}

.party-label {
    width: 80px;
    font-weight: bold;
    flex-shrink: 0;
}

.party-value {
    border-bottom: 1px solid #000;
    flex: 1;
    min-width: 200px;
    padding-bottom: 2px;
    display: inline-block;
}

.party-value:empty::after {
    content: '\00a0';
}

.contract-date-location {
    display: flex;
    justify-content: space-between;
    margin-bottom: 20px;
    font-size: 13px;
}

.date-location-item {
    display: flex;
    align-items: baseline;
}

.date-location-label {
    margin-right: 5px;
    font-weight: bold;
}

.date-location-value {
    border-bottom: 1px solid #000;
    min-width: 150px;
    padding-bottom: 2px;
    display: inline-block;
}

.date-location-value:empty::after {
    content: '\00a0';
}

.regulatory-info {
    text-align: center;
    font-size: 11px;
    color: #666;
    margin-bottom: 20px;
    padding-top: 10px;
    border-top: 1px solid #ddd;
}

.notice-section {
    margin-bottom: 20px;
    padding: 10px;
    background-color: #f9f9f9;
    border: 1px solid #ddd;
    font-size: 11px;
    line-height: 1.8;
}

.notice-title {
    font-weight: bold;
    font-size: 13px;
    margin-bottom: 8px;
}

.notice-content {
    margin-bottom: 5px;
}

.section-title {
    font-weight: bold;
    font-size: 14px;
    margin-top: 20px;
    margin-bottom: 10px;
    page-break-after: avoid;
}

.section-subtitle {
    font-weight: bold;
    font-size: 13px;
    margin-top: 15px;
    margin-bottom: 8px;
}

.item-table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
    margin-bottom: 20px;
    font-size: 11px;
    table-layout: fixed;
}

.item-table th,
.item-table td {
    border: 1px solid #000;
    padding: 6px 4px;
    vertical-align: middle;
    text-align: center;
    word-wrap: break-word;
}

.item-table th {
    background-color: #f0f0f0;
    font-weight: bold;
    font-size: 12px;
}

.item-table td.text-left {
    text-align: left;
}

.item-table td.text-right {
    text-align: right;
}

.clause-content {
    font-size: 12px;
    line-height: 1.8;
    margin-bottom: 12px;
}

.checkbox-item {
    margin-bottom: 6px;
    display: flex;
    align-items: baseline;
}

.checkbox {
    width: 14px;
    height: 14px;
    border: 1px solid #000;
    display: inline-block;
    margin-right: 3px;
    margin-left: 2px;
    margin-top: 0 !important;
    flex-shrink: 0;
    vertical-align: middle;
    position: relative;
    top: 2px;
}

/* 覆盖 Bootstrap 的 checkbox 样式干扰 */
.checkbox+.checkbox {
    margin-top: 0 !important;
}

.checkbox-label {
    margin-right: 8px;
}

.fill-field {
    border-bottom: 1px solid #000;
    min-width: 100px;
    display: inline-block;
    padding-bottom: 2px;
    margin: 0 3px;
}

.fill-field:empty::after {
    content: '\00a0';
}

.signature-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 30px;
    font-size: 11px;
    table-layout: fixed;
}

.signature-table td {
    border: none;
    padding: 8px 6px;
    vertical-align: top;
    width: 50%;
}

.signature-table th {
    border: none;
    padding: 8px 6px;
    background-color: transparent;
    font-weight: bold;
    text-align: center;
    font-size: 12px;
}

.signature-info {
    margin-bottom: 6px;
    font-size: 11px;
    line-height: 1.8;
    display: flex;
    align-items: baseline;
}

.signature-label {
    font-weight: bold;
    margin-right: 8px;
    text-align: right;
    min-width: 120px;
    flex-shrink: 0;
}

.signature-value {
    border-bottom: 1px solid #000;
    min-width: 150px;
    flex: 1;
    display: inline-block;
    padding-bottom: 2px;
    vertical-align: baseline;
}

.signature-value:empty::after {
    content: '\00a0';
}

/* PDF和打印优化 */
@media print {
    * {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    .print-format {
        padding: 0 !important;
        margin: 0 !important;
        font-size: 11px !important;
    }

    .item-table {
        border-collapse: collapse !important;
        width: 100% !important;
        table-layout: fixed !important;
    }

    .item-table th,
    .item-table td {
        border: 1px solid #000 !important;
        padding: 5px 3px !important;
    }

    .item-table th {
        background-color: #f0f0f0 !important;
    }

    .signature-table th,
    .signature-table td {
        border: none !important;
        padding: 6px 4px !important;
    }

    .signature-table th {
        background-color: transparent !important;
    }

    .section-title,
    .section-subtitle {
        page-break-after: avoid !important;
    }

    .notice-section {
        page-break-inside: avoid !important;
    }
}

@page {
    margin: 8mm 10mm;
    size: A4;
}

.print-format {
    box-sizing: border-box;
    width: 100%;
}

/* 确保PDF导出时边距正确 */
body {
    margin: 0 !important;
    padding: 0 !important;
}

/* 覆盖Frappe默认的print-format padding */
body .print-format {
    padding: 0 !important;
    margin: 0 !important;
}

/* ============================================
   合同内容区域样式 (contract-content)
   ============================================ */

/* 主容器样式 */
.contract-content {
    font-family: "HarmonyOS Sans SC", "HarmonyOSHans-Regular", "PingFangSC-Regular", "Microsoft YaHei", "Arial", "Helvetica", sans-serif;
    font-size: 13px;
    line-height: 1.8;
    color: #171717;
    text-align: justify;
    margin: 0;
    padding: 0;
}

/* 前言说明文字颜色统一为黑色 */
.regulatory-info,
.regulatory-info.text-muted {
    color: #171717 !important;
}

/* 章节标题样式（第一条、第二条等） */
.contract-content .section-title {
    font-size: 15px;
    font-weight: 700;
    color: #171717;
    margin-top: 24px;
    margin-bottom: 16px;
    line-height: 1.6;
    letter-spacing: 0.5px;
}

/* 第一个章节标题不需要上边距 */
.contract-content .section-title:first-child {
    margin-top: 0;
}

/* 子章节标题样式（1.1、1.2等） */
.contract-content .section-subtitle {
    font-size: 14px;
    font-weight: 600;
    color: #2c3e50;
    margin-top: 18px;
    margin-bottom: 12px;
    line-height: 1.6;
    letter-spacing: 0.3px;
}

/* 条款内容容器 */
.contract-content .clause-content {
    margin-bottom: 16px;
    padding-left: 1.5em;
}

/* 条款项样式 */
.contract-content .clause-item {
    font-size: 13px;
    line-height: 2;
    color: #171717;
    margin-bottom: 10px;
    text-align: justify;
    text-indent: 0;
    padding-left: 0;
}

/* 缩进条款项（如 4.1.2.1、4.1.2.2 等） */
.contract-content .clause-item.indent {
    padding-left: 2em;
    text-indent: -2em;
    margin-left: 0;
}

/* 下划线样式优化 */
.contract-content u {
    text-decoration: underline;
    text-underline-offset: 0.15em;
    text-decoration-thickness: 1px;
    text-decoration-color: #171717;
    padding: 0 2px;
}

/* 表格样式 */
.contract-content .item-table,
.item-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 12px;
    margin-bottom: 16px;
    font-size: 12px;
    border: 1px solid #000 !important;
}

.contract-content .item-table thead,
.item-table thead {
    background-color: #f5f5f5;
}

.contract-content .item-table th,
.item-table th {
    font-weight: 600;
    color: #171717;
    padding: 10px 8px;
    text-align: center;
    border: 1px solid #000 !important;
    background-color: #f5f5f5;
    vertical-align: middle;
}

.contract-content .item-table td,
.item-table td {
    padding: 8px;
    border: 1px solid #000 !important;
    text-align: center;
    vertical-align: middle;
    line-height: 1.6;
}

.contract-content .item-table tbody tr {
    background-color: #fff;
}

/* 表格中的左对齐文本（如备注列） */
.contract-content .item-table td[style*="text-align: left"] {
    text-align: left !important;
    padding-left: 10px;
}

/* 防止单价、总价列换行 */
.contract-content .item-table td:nth-child(5),
.contract-content .item-table td:nth-child(6),
.item-table td:nth-child(5),
.item-table td:nth-child(6) {
    white-space: nowrap;
}

/* 防止数量列换行（仅当没有white-space: normal样式时） */
.contract-content .item-table td:nth-child(3):not([style*="white-space: normal"]),
.item-table td:nth-child(3):not([style*="white-space: normal"]) {
    white-space: nowrap;
}

/* 通讯地址列允许换行 */
.item-table td[style*="white-space: normal"],
.contract-content .item-table td[style*="white-space: normal"] {
    white-space: normal !important;
    word-wrap: break-word;
    word-break: break-all;
}

/* 签名表格样式 */
.signature-table,
.print-format-wrapper .signature-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 24px;
    margin-bottom: 0;
    font-size: 12px;
    border: 1px solid #000;
}

.signature-table th,
.print-format-wrapper .signature-table th {
    font-weight: 600;
    color: #171717;
    padding: 12px;
    text-align: center;
    border: 1px solid #000;
    vertical-align: middle;
    width: 50%;
}

.signature-table td,
.print-format-wrapper .signature-table td {
    padding: 10px 20px;
    border: 1px solid #000;
    border-bottom-color: transparent;
    vertical-align: top;
    text-align: left;
    line-height: 1.45;
}

.signature-table tbody tr:last-child td,
.print-format-wrapper .signature-table tbody tr:last-child td {
    border-bottom-color: #000;
}

/* 签名信息样式 */
.signature-info {
    display: flex;
    align-items: flex-start;
    margin-bottom: 0;
}

.signature-label {
    font-weight: 600;
    color: #171717;
    display: inline-block;
    min-width: 80px;
    flex-shrink: 0;
    margin-bottom: 0;
}

.signature-value {
    color: #171717;
    flex: 1;
    word-wrap: break-word;
    word-break: break-all;
    margin-bottom: 0;
}

/* 响应式调整 */
@media print {
    /* 移除 .contract-content 的 page-break-inside: avoid; 
       允许合同内容在页面中自然分页，避免第一页空白 */
    
    .contract-content .section-title {
        page-break-after: avoid;
    }
    
    .contract-content .section-subtitle {
        page-break-after: avoid;
    }
    
    .contract-content .item-table {
        page-break-inside: avoid;
    }
    
    .signature-table {
        page-break-inside: avoid;
    }
}

/* 确保表格在打印时正确显示 */
.contract-content .item-table,
.signature-table {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

